(45229, 'Lamentations 3:2', 'Lamentations', 3, 2, 'هغۀ زۀ په راښکلو تيارې ته راوستم چې هيڅ رڼا په کښې نۀ وه.', 'هغۀ زۀ په راشکلو تیارې ته راوستم چې هیچ رنا په کشې نۀ وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45230, 'Lamentations 3:3', 'Lamentations', 3, 3, 'يقيناً چې هغۀ زما په خلاف خپل لاس ټوله ورځ بار بار راوچت کړو.', 'یقینا چې هغۀ زما په خلاف خپل لاس توله ورج بار بار راوچت کرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45231, 'Lamentations 3:4', 'Lamentations', 3, 4, 'هغۀ زما ټول ځان په وهلو تک شين کړو او زما هډُوکى يې مات کړل.', 'هغۀ زما تول جان په وهلو تک شین کرو او زما هدوکی یې مات کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45232, 'Lamentations 3:5', 'Lamentations', 3, 5, 'هغۀ زۀ په تريخوالى او غمونو کښې ايسار او راګېر کړے يم.', 'هغۀ زۀ په تریخوالی او غمونو کشې ایسار او راګېر کرے یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45233, 'Lamentations 3:6', 'Lamentations', 3, 6, 'هغۀ زۀ په زوړ قبر کښې په توره تياره کښې کښېنولم.', 'هغۀ زۀ په زور قبر کشې په توره تیاره کشې کشېنولم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45234, 'Lamentations 3:7', 'Lamentations', 3, 7, 'هغۀ زۀ په دېوالونو کښې راګېر کړم چې ونۀ تښتم او په درنو زنځيرونو يې تړلے يم.', 'هغۀ زۀ په دېوالونو کشې راګېر کرم چې ونۀ تشتم او په درنو زنجیرونو یې ترلے یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45235, 'Lamentations 3:8', 'Lamentations', 3, 8, 'تر دې چې ما آواز وکړو او مدد دپاره په چغو وژړېدم، هغۀ زما دُعاګانو ته توجو نۀ ورکوله.', 'تر دې چې ما اواز وکرو او مدد دپاره په چغو وژرېدم، هغۀ زما دعاګانو ته توجو نۀ ورکوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45236, 'Lamentations 3:9', 'Lamentations', 3, 9, 'هغۀ زما لارې د تراشلے شوو کاڼو په دېوال بندې کړى دى، او هغۀ زما لارې ګډې وډې کړې دى.', 'هغۀ زما لارې د تراشلے شوو کانو په دېوال بندې کری دی، او هغۀ زما لارې ګدې ودې کرې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45237, 'Lamentations 3:10', 'Lamentations', 3, 10, 'هغه لکه د مېلو زما په انتظار کښې پروت دے او لکه چې زمرے د حملې دپاره پټ شوے وى.', 'هغه لکه د مېلو زما په انتظار کشې پروت دے او لکه چې زمرے د حملې دپاره پت شوے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45238, 'Lamentations 3:11', 'Lamentations', 3, 11, 'هغۀ زۀ د لارې نه بې‌لارې کړم، او ټوټې ټوټې يې کړم. او هغۀ زۀ وران ويجاړ او بې‌ياره بې‌مددګاره پرېښودم.', 'هغۀ زۀ د لارې نه بې‌لارې کرم، او توتې توتې یې کرم. او هغۀ زۀ وران ویجار او بې‌یاره بې‌مددګاره پرېشودم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45239, 'Lamentations 3:12', 'Lamentations', 3, 12, 'هغۀ خپله لينده راښکله او د خپلو غشو دپاره يې نښه وګرځولم.', 'هغۀ خپله لینده راشکله او د خپلو غشو دپاره یې نشه وګرجولم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45240, 'Lamentations 3:13', 'Lamentations', 3, 13, 'هغۀ زما زړۀ سورے سورے کړو او د خپل تيردان په غشو يې وويشتم.', 'هغۀ زما زرۀ سورے سورے کرو او د خپل تیردان په غشو یې وویشتم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45241, 'Lamentations 3:14', 'Lamentations', 3, 14, 'زۀ د خپلو خلقو د خندا ذريعه شوم، ټوله ورځ ما ته پيغورونه کوى.', 'زۀ د خپلو خلقو د خندا ذریعه شوم، توله ورج ما ته پیغورونه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45242, 'Lamentations 3:15', 'Lamentations', 3, 15, 'هغۀ زۀ په ترخو خوراکونو موړ کړم، او د څښلو دپاره يې د تريخ ګنډير نه ډکه پياله راکړه.', 'هغۀ زۀ په ترخو خوراکونو مور کرم، او د چشلو دپاره یې د تریخ ګندیر نه دکه پیاله راکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45243, 'Lamentations 3:16', 'Lamentations', 3, 16, 'هغۀ زما په غاښونو کښې باجرى ورکړه، او په خاورو ايرو کښې يې ومنډلم.', 'هغۀ زما په غاشونو کشې باجری ورکره، او په خاورو ایرو کشې یې ومندلم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45244, 'Lamentations 3:17', 'Lamentations', 3, 17, 'زما زړۀ د سلامتيا نه خالى شوے دے او ما نه هېر دى چې خوشحالى څۀ ته وائى.', 'زما زرۀ د سلامتیا نه خالی شوے دے او ما نه هېر دی چې خوشحالی چۀ ته وایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45245, 'Lamentations 3:18', 'Lamentations', 3, 18, 'نو زۀ دا وايم، ”زما طمع او اُميد لاړو او څۀ چې زما د مالِک خُدائ نه اُميد وو هغه ختم شو.“', 'نو زۀ دا وایم، ”زما طمع او امید لارو او چۀ چې زما د مالک خدای نه امید وو هغه ختم شو.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45246, 'Lamentations 3:19', 'Lamentations', 3, 19, 'زما مصيبتونه او خوار و زار ګرځېدل ما ته ياديږى، او هغه ما ته د ګنډير نه هم تراخۀ دى.', 'زما مصیبتونه او خوار و زار ګرجېدل ما ته یادیزی، او هغه ما ته د ګندیر نه هم تراخۀ دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45247, 'Lamentations 3:20', 'Lamentations', 3, 20, 'زۀ بار بار د هغۀ په حقله سوچ کوم او زما روح په ما کښې پرېشانه دے.', 'زۀ بار بار د هغۀ په حقله سوچ کوم او زما روح په ما کشې پرېشانه دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45248, 'Lamentations 3:21', 'Lamentations', 3, 21, 'خو بيا هم زۀ په خپل سوچ کښې دا راولم او په دې وجه زۀ بيا هم اُميدوار يم.', 'خو بیا هم زۀ په خپل سوچ کشې دا راولم او په دې وجه زۀ بیا هم امیدوار یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45249, 'Lamentations 3:22', 'Lamentations', 3, 22, 'د مالِک خُدائ پائيداره مينه هيڅکله نۀ ختميږى او د هغۀ رحم هيڅکله نۀ ختميږى.', 'د مالک خدای پاییداره مینه هیچکله نۀ ختمیزی او د هغۀ رحم هیچکله نۀ ختمیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45250, 'Lamentations 3:23', 'Lamentations', 3, 23, 'د هغۀ رحم او مينه هر سحر نوے او تازه کيږى او د هغۀ وفادارى بې‌شانه لويه ده.', 'د هغۀ رحم او مینه هر سحر نوے او تازه کیزی او د هغۀ وفاداری بې‌شانه لویه ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45251, 'Lamentations 3:24', 'Lamentations', 3, 24, '”مالِک خُدائ زما نصيب دے،“ او زۀ خپل ځان ته دا وايم، ”نو په دې وجه زۀ به د هغۀ نه اُميد ساتم.“', '”مالک خدای زما نصیب دے،“ او زۀ خپل جان ته دا وایم، ”نو په دې وجه زۀ به د هغۀ نه امید ساتم.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45252, 'Lamentations 3:25', 'Lamentations', 3, 25, 'مالِک خُدائ هغه چا سره ښۀ دے څوک چې په هغۀ باور کوى او هغه کس څوک چې د هغۀ تلاش کوى.', 'مالک خدای هغه چا سره شۀ دے چوک چې په هغۀ باور کوی او هغه کس چوک چې د هغۀ تلاش کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45253, 'Lamentations 3:26', 'Lamentations', 3, 26, 'دا ښۀ ده چې يو کس په خاموشۍ سره انتظار وکړى، د مالِک خُدائ خلاصون ته انتظار وکړى.', 'دا شۀ ده چې یو کس په خاموشی سره انتظار وکری، د مالک خدای خلاصون ته انتظار وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45254, 'Lamentations 3:27', 'Lamentations', 3, 27, 'د يو کس دپاره دا ښۀ ده چې په ځوانۍ کښې جغ يوسى،', 'د یو کس دپاره دا شۀ ده چې په جوانی کشې جغ یوسی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45255, 'Lamentations 3:28', 'Lamentations', 3, 28, 'چې په خاموشۍ کښې ځان له کښېنى، څۀ چې مالِک خُدائ پرې اېښے وى.', 'چې په خاموشی کشې جان له کشېنی، چۀ چې مالک خدای پرې اېشے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_28.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45256, 'Lamentations 3:29', 'Lamentations', 3, 29, 'هغه دې خپل ځان پړمخې په خاورو کښې وغورزوى، کېدے شى چې څۀ اُميد پاتې وى.', 'هغه دې خپل جان پرمخې په خاورو کشې وغورزوی، کېدے شی چې چۀ امید پاتې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45257, 'Lamentations 3:30', 'Lamentations', 3, 30, 'ظالم ته دې د وهلو دپاره خپل مخ ورواړوى او د هغۀ د لاسه دې بې‌عزتى قبوله کړى.', 'ظالم ته دې د وهلو دپاره خپل مخ ورواروی او د هغۀ د لاسه دې بې‌عزتی قبوله کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_30.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45258, 'Lamentations 3:31', 'Lamentations', 3, 31, 'ځکه مالِک به انسان د تل دپاره نۀ رد کوى.', 'جکه مالک به انسان د تل دپاره نۀ رد کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45259, 'Lamentations 3:32', 'Lamentations', 3, 32, 'دا کۀ هغه غم راولى، هغه به رحم هم کوى، د هغه مينې په مطابق چې ډېره او پائيداره ده.', 'دا کۀ هغه غم راولی، هغه به رحم هم کوی، د هغه مینې په مطابق چې دېره او پاییداره ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45260, 'Lamentations 3:33', 'Lamentations', 3, 33, 'هغه چا ته په تکليف رسولو نۀ خوشحاليږى او نۀ څوک په غم آخته کوى.', 'هغه چا ته په تکلیف رسولو نۀ خوشحالیزی او نۀ چوک په غم اخته کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843);